Lemma rchain_cells_frame : forall (M M' : word -> option byte) lo0 lo fp RC,
  HAR.rchain L ar M lo fp RC ->
  (HAR.fvalid ar lo fp -> lo0 <= fp - 16) ->
  (forall a v, lo0 <= a -> a + 8 <= top -> a mod 8 = 0 -> 0 <= v < 2 ^ 64 -> cis M a 8 v -> cis M' a 8 v) ->
  HAR.rchain L ar M' lo fp RC.
